def final_spiral_sum(W):
    Q = [(1, 1), (W, 1), (W, W), (1, W)]
    m = 1
    while True:
        Q4m = (m, m+1)
        Q4m1 = (W-m, m+1)
        Q4m2 = (W-m, W-m)
        Q4m3 = (m+1, W-m)

        new_points = [Q4m, Q4m1, Q4m2, Q4m3]
        added = False
        for p in new_points:
            x, y = p
            if 1 <= x <= W and 1 <= y <= W and p not in Q:
                Q.append(p)
                added = True
            else:
                break
        if not added:
            break
        m += 1

    total_time = 0
    for i in range(len(Q) - 1):
        total_time += abs(Q[i][0] - Q[i+1][0]) + abs(Q[i][1] - Q[i+1][1])
    return total_time

